export interface WatchdogResult {
	shouldAbort: boolean
	reason?: "loop_detected" | "timeout_exceeded"
	userNotice?: string
}

export interface RepetitionDetectorResult {
	hasLoop: boolean
	repeatedContent?: string
}

export type RepetitionDetector = (text: string) => RepetitionDetectorResult

export class ThinkingWatchdog {
	private startTime: number = 0
	private readonly maxDurationMs: number
	private readonly repetitionDetector?: RepetitionDetector

	constructor(maxDurationMs: number = 120_000, repetitionDetector?: RepetitionDetector) {
		this.maxDurationMs = maxDurationMs
		this.repetitionDetector = repetitionDetector
	}

	start(): void {
		this.startTime = Date.now()
	}

	check(accumulatedReasoning: string): WatchdogResult {
		// 1. Check if (Date.now() - this.startTime) > this.maxDurationMs -> timeout_exceeded
		if (this.startTime > 0 && Date.now() - this.startTime > this.maxDurationMs) {
			return {
				shouldAbort: true,
				reason: "timeout_exceeded",
				userNotice: "Thinking duration exceeded limit",
			}
		}

		// 2. Check for repetitive reasoning loop
		if (
			accumulatedReasoning.length >= 80 &&
			this.repetitionDetector !== undefined
		) {
			const result = this.repetitionDetector(accumulatedReasoning)
			if (result.hasLoop) {
				return {
					shouldAbort: true,
					reason: "loop_detected",
					userNotice: "Repetitive reasoning loop detected",
				}
			}
		}

		// 3. Default: no abort
		return { shouldAbort: false }
	}

	reset(): void {
		this.startTime = 0
	}
}
